struct query {
    int x1, y1, x2, y2, id;
};

struct SegmentTree {
    int n;
    vector<int> tree;

    SegmentTree(int n) : n(n), tree(4 * n + 5, 0) {}

    void update(int node, int start, int end, int idx, int val) {
        if (start == end) {
            tree[node] = val;
            return;
        }
        int mid = (start + end) / 2;
        if (idx <= mid) update(2 * node, start, mid, idx, val);
        else update(2 * node + 1, mid + 1, end, idx, val);
        tree[node] = min(tree[2 * node], tree[2 * node + 1]);
    }

    int query(int node, int start, int end, int l, int r) {
        if (r < start || end < l) return INT_MAX;
        if (l <= start && end <= r) return tree[node];
        int mid = (start + end) / 2;
        return min(query(2 * node, start, mid, l, r),
                   query(2 * node + 1, mid + 1, end, l, r));
    }

    void update(int idx, int val) {
        update(1, 1, n, idx, val);
    }

    int query(int l, int r) {
        return query(1, 1, n, l, r);
    }
};

int main() {
    #ifdef ONLINE_JUDGE
    freopen("storehouse.inp", "r", stdin);
    freopen("storehouse.out", "w", stdout);
    #endif
    ios_base::sync_with_stdio(false);
    cin.tie(0);

    int n, m, k, q;
    cin >> n >> m >> k >> q;

    vector<vector<int>> by_row(m + 1);
    vector<vector<int>> by_col(n + 1);

    for (int i = 0; i < k; i++) {
        int u, v;
        cin >> u >> v;
        by_row[v].push_back(u);
        by_col[u].push_back(v);
    }

    vector<query> queries(q);
    vector<vector<int>> by_y2(m + 1);
    vector<vector<int>> by_x2(n + 1);

    for (int i = 0; i < q; i++) {
        cin >> queries[i].x1 >> queries[i].y1 >> queries[i].x2 >> queries[i].y2;
        queries[i].id = i;
        by_y2[queries[i].y2].push_back(i);
        by_x2[queries[i].x2].push_back(i);
    }

    vector<bool> safe(q, false);
    SegmentTree col(n);
    for (int y = 1; y <= m; ++y) {
        for (int x : by_row[y]) {
            col.update(x, y);
        }
        for (int q_idx : by_y2[y]) {
            const auto& q = queries[q_idx];
            if (col.query(q.x1, q.x2) >= q.y1) {
                safe[q_idx] = true;
            }
        }
    }
    SegmentTree row(m);
    for (int x = 1; x <= n; ++x) {
        for (int y : by_col[x]) {
            row.update(y, x);
        }
        for (int q_idx : by_x2[x]) {
            const auto& q = queries[q_idx];
            if (row.query(q.y1, q.y2) >= q.x1) {
                safe[q_idx] = true;
            }
        }
    }
    for (int i = 0; i < q; i++) {
        cout << (safe[i] ? 1 : 0) << "\n";
    }
}